// verify_dataset.ts
//
// bun run src/verify_dataset.ts [path-to-jsonl]
//
// Loads out/schema-dataset.jsonl (generated by generate_ai_datasets.ts),
// validates every record with the same gates as the GUI runner
// (packages/gui/web.ts compileDatasetRow): schema conversion -> ArkType value
// conformance -> fresh SchemaAnalyzer plan -> compileLayoutPlanProgram support.
// Reports per-record pass/fail plus aggregate stats and the most common issues.

import { readFile } from "node:fs/promises"
import { join } from "node:path"
import { scope } from "arktype"
import { SchemaAnalyzer } from "@schema-pop/core"
import { jsonSchemaToType } from "@ark/json-schema"
import { compileLayoutPlanProgram } from "../../engine-ts/src/index.ts"

const INPUT = process.argv[2] ?? join(import.meta.dir, "../out/schema-dataset.jsonl")

type LayoutPlan = Parameters<typeof compileLayoutPlanProgram>[0]

type DatasetRecord = {
	seed: number
	id: number
	task: string
	/** New compact dataset shape (fresh analysis preferred). */
	rawSchema?: unknown
	/** Backward compatibility with the current dataset. */
	schema?: unknown
	value: unknown
	sampleText: string
	/** Backward compatibility only; fresh analysis is preferred when a schema is present. */
	analysis?: { plan?: LayoutPlan; warnings?: unknown[]; errors?: unknown[] }
	plan: string
}

type ArkValidator = {
	assert(value: unknown): unknown
}

type Issue = {
	category: string
	message: string
}

function formatError(error: unknown): string {
	if (typeof error === "string") return error
	if (error instanceof Error) return error.message
	if (error && typeof error === "object" && "message" in error) {
		const message = (error as { message?: unknown }).message
		if (typeof message === "string" && message.length > 0) return message
	}
	try {
		return JSON.stringify(error)
	} catch {
		return String(error)
	}
}

// Mirrors packages/gui/web.ts compileDatasetRow: a row is supported only when
// a plan can be derived from its schema AND that plan compiles into a Layout
// Plan constraint program. Legacy rows fall back to the stored analysis.plan.
function checkRecord(record: DatasetRecord): Issue[] {
	const issues: Issue[] = []

	const rawSchema = record.rawSchema ?? record.schema
	let arkType: ArkValidator | null = null
	let plan: LayoutPlan | undefined

	if (rawSchema !== undefined) {
		let converted: unknown
		try {
			converted = jsonSchemaToType(rawSchema as any)
		} catch (error) {
			issues.push({ category: "schema-conversion", message: `crashed: ${formatError(error)}` })
			return issues
		}
		if (converted === undefined) {
			issues.push({ category: "schema-conversion", message: "jsonSchemaToType returned undefined" })
		} else {
			arkType = converted as unknown as ArkValidator
			try {
				const module = scope({ value: converted })
				const analysis = new SchemaAnalyzer().analyze(module, { mode: "binary" })
				if (!analysis.plan || analysis.errors.length > 0) {
					issues.push({ category: "analyzer", message: `SchemaAnalyzer failed: ${JSON.stringify(analysis.errors)}` })
				} else {
					plan = analysis.plan as LayoutPlan
				}
			} catch (error) {
				issues.push({ category: "analyzer", message: `crashed: ${formatError(error)}` })
			}
		}
	} else if (record.analysis?.plan) {
		// Old fixture fallback: usable for constraint debugging, but the generated
		// value cannot be validated without the original schema.
		plan = record.analysis.plan
	} else {
		issues.push({ category: "schema", message: "row has neither rawSchema/schema nor analysis.plan" })
	}

	if (arkType) {
		try {
			arkType.assert(record.value)
		} catch (error) {
			issues.push({ category: "value-validation", message: formatError(error) })
		}
	}

	if (plan) {
		// Rows that fail here are the "UNSUPPORTED" ones skipped by the GUI batch
		// runner (runAllStructuredRows) — the LayoutPlan compiler cannot encode them.
		try {
			compileLayoutPlanProgram(plan)
		} catch (error) {
			issues.push({ category: "layoutplan", message: `unsupported: ${formatError(error)}` })
		}
	}

	return issues
}

type RecordOutcome = {
	index: number
	record: DatasetRecord | null
	issues: Issue[]
}

const text = await readFile(INPUT, "utf8")
const lines = text.split("\n").filter((line) => line.trim().length > 0)

const outcomes: RecordOutcome[] = []

for (const [index, line] of lines.entries()) {
	let record: DatasetRecord
	try {
		record = JSON.parse(line) as DatasetRecord
	} catch (error) {
		outcomes.push({ index, record: null, issues: [{ category: "json-parse", message: formatError(error) }] })
		continue
	}

	outcomes.push({ index, record, issues: checkRecord(record) })
}

// --- stats -----------------------------------------------------------------

const passed = outcomes.filter((outcome) => outcome.issues.length === 0)
const failed = outcomes.filter((outcome) => outcome.issues.length > 0)

const byCategory = new Map<string, number>()
const byMessage = new Map<string, number>()
for (const outcome of failed) {
	for (const issue of outcome.issues) {
		byCategory.set(issue.category, (byCategory.get(issue.category) ?? 0) + 1)
		byMessage.set(issue.message, (byMessage.get(issue.message) ?? 0) + 1)
	}
}

const topIssues = [...byMessage.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10)

// --- report -----------------------------------------------------------------

const pct = (count: number) =>
	`${(lines.length > 0 ? (count / lines.length) * 100 : 0).toFixed(1)}%`

console.log("\n=== dataset verification ===")
console.log(`input:      ${INPUT}`)
console.log(`records:    ${lines.length}`)
console.log(`passed:     ${passed.length} (${pct(passed.length)})`)
console.log(`failed:     ${failed.length} (${pct(failed.length)})`)
console.log(`by category:`)
for (const [category, count] of byCategory) {
	console.log(`  ${category}: ${count}`)
}
if (byCategory.size === 0) console.log("  (none)")

if (failed.length > 0) {
	console.log("\n--- failed records ---")
	for (const outcome of failed) {
		const record = outcome.record
		const label = record ? `[${outcome.index}] id=${record.id} seed=${record.seed}` : `[${outcome.index}] (unparseable)`
		console.log(`✗ ${label} — ${record?.task ?? ""}`)
		for (const issue of outcome.issues) {
			console.log(`    • [${issue.category}] ${issue.message}`)
		}
	}

	console.log("\n--- most common issues ---")
	if (topIssues.length === 0) {
		console.log("  (none)")
	} else {
		for (const [message, count] of topIssues) {
			console.log(`  ${count}× ${message}`)
		}
	}
}

if (passed.length > 0) {
	console.log("\n--- passed records ---")
	for (const outcome of passed) {
		const record = outcome.record!
		console.log(`✓ [${outcome.index}] id=${record.id} seed=${record.seed} — ${record.task}`)
	}
}

console.log("")
